using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Diagnostics;using System.Threading;using System.Windows;using System.Windows.Interop;using System.Windows.Threading;using System.Web.Script.Serialization;
namespace DesktopBox {
public sealed class TaskbarVisibility:IDisposable {
 [StructLayout(LayoutKind.Sequential)]struct Rect {public int Left,Top,Right,Bottom;}
 [StructLayout(LayoutKind.Sequential)]struct Appbar {public int Size;public IntPtr Window;public uint Callback,Edge;public Rect Rectangle;public IntPtr Parameter;}
 delegate bool EnumProc(IntPtr window,IntPtr extra);delegate IntPtr KeyProc(int code,IntPtr message,IntPtr data);delegate void EventProc(IntPtr hook,uint ev,IntPtr window,int obj,int child,uint thread,uint time);
 [DllImport("user32.dll")]static extern bool EnumWindows(EnumProc callback,IntPtr extra);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetClassName(IntPtr window,System.Text.StringBuilder name,int length);
 [DllImport("user32.dll")]static extern bool IsWindow(IntPtr window);
 [DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr window);
 [DllImport("user32.dll")]static extern bool ShowWindow(IntPtr window,int command);
 [DllImport("user32.dll",SetLastError=true)]static extern IntPtr SetWindowsHookEx(int type,KeyProc proc,IntPtr module,uint thread);
 [DllImport("user32.dll")]static extern bool UnhookWindowsHookEx(IntPtr hook);
 [DllImport("user32.dll")]static extern IntPtr CallNextHookEx(IntPtr hook,int code,IntPtr message,IntPtr data);
 [DllImport("user32.dll")]static extern short GetAsyncKeyState(int key);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern IntPtr GetModuleHandle(string name);
 [DllImport("user32.dll")]static extern IntPtr SetWinEventHook(uint min,uint max,IntPtr module,EventProc callback,uint process,uint thread,uint flags);
 [DllImport("user32.dll")]static extern bool UnhookWinEvent(IntPtr hook);
 [DllImport("shell32.dll")]static extern UIntPtr SHAppBarMessage(uint message,ref Appbar data);
 readonly Dispatcher dispatcher;readonly DispatcherTimer repair;readonly KeyProc keyCallback;readonly EventProc eventCallback;readonly Func<IEnumerable<IntPtr>> targets;readonly bool testing;readonly string optionsPath;readonly Dictionary<IntPtr,bool> originals=new Dictionary<IntPtr,bool>();IntPtr keyHook,eventHook;EventWaitHandle guardStop;Process guard;bool disposed,keyDown;int originalState;public bool Hidden{get;private set;}public string Error="";public int Toggles;public bool Ready{get{return testing||keyHook!=IntPtr.Zero;}}
 public TaskbarVisibility(bool test=false,Func<IEnumerable<IntPtr>> windows=null){testing=test;dispatcher=Dispatcher.CurrentDispatcher;targets=windows??Taskbars;optionsPath=Path.Combine(Program.S.Root,"taskbar-visibility-options.json");repair=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(500)};repair.Tick+=(o,e)=>Enforce();keyCallback=Keyboard;eventCallback=ShellShown;if(test)return;
  originalState=ReadAppbarState();foreach(var window in targets())originals[window]=IsWindowVisible(window);try{StartGuard();keyHook=SetWindowsHookEx(13,keyCallback,GetModuleHandle(null),0);if(keyHook==IntPtr.Zero)throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());eventHook=SetWinEventHook(0x8002,0x8002,IntPtr.Zero,eventCallback,0,0,0);bool hide=true;if(File.Exists(optionsPath))try{hide=new JavaScriptSerializer().Deserialize<Dictionary<string,bool>>(File.ReadAllText(optionsPath))["hidden"];}catch{}SetHidden(hide,false);repair.Start();}catch(Exception ex){Error=ex.Message;Restore();}Application.Current.Exit+=(o,e)=>Dispose();Application.Current.SessionEnding+=(o,e)=>Dispose();Record();}
 public static bool WindowShown(IntPtr window){return IsWindowVisible(window);}
 public static object Snapshot(){return new{time=DateTimeOffset.Now.ToString("o"),appbarState=ReadAppbarState(),windows=Taskbars().Select(window=>new{handle=window.ToInt64(),visible=IsWindowVisible(window)}).ToArray()};}
 public static IEnumerable<IntPtr> Taskbars(){var windows=new List<IntPtr>();EnumWindows((window,extra)=>{if(IsTaskbar(window))windows.Add(window);return true;},IntPtr.Zero);return windows;}
 static bool IsTaskbar(IntPtr window){var name=new System.Text.StringBuilder(96);GetClassName(window,name,name.Capacity);return name.ToString()=="Shell_TrayWnd"||name.ToString()=="Shell_SecondaryTrayWnd";}
 public static int ReadAppbarState(){var data=new Appbar{Size=Marshal.SizeOf(typeof(Appbar)),Window=Taskbars().FirstOrDefault()};return (int)SHAppBarMessage(4,ref data).ToUInt64();}
 static void SetAppbarState(int state){var data=new Appbar{Size=Marshal.SizeOf(typeof(Appbar)),Window=Taskbars().FirstOrDefault(),Parameter=new IntPtr(state)};SHAppBarMessage(10,ref data);}
 void StartGuard(){string name="Local\\rushbin-taskbar-"+Process.GetCurrentProcess().Id+"-"+Guid.NewGuid().ToString("N");guardStop=new EventWaitHandle(false,EventResetMode.ManualReset,name);byte[] bytes;using(var stream=typeof(TaskbarVisibility).Assembly.GetManifestResourceStream("DeskBox.TaskbarGuard")){if(stream==null)throw new FileNotFoundException("任务栏恢复保护未打包");using(var memory=new MemoryStream()){stream.CopyTo(memory);bytes=memory.ToArray();}}string hash;using(var sha=System.Security.Cryptography.SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","");string folder=Path.Combine(Program.S.Root,"native");Directory.CreateDirectory(folder);string file=Path.Combine(folder,"TaskbarGuard-"+hash.Substring(0,16)+".exe");if(!File.Exists(file))File.WriteAllBytes(file,bytes);else{using(var sha=System.Security.Cryptography.SHA256.Create())if(BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(file))).Replace("-","")!=hash)throw new InvalidDataException("任务栏恢复保护校验失败");}guard=Process.Start(new ProcessStartInfo(file,Process.GetCurrentProcess().Id+" "+name+" "+originalState){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});if(guard==null||guard.WaitForExit(100))throw new InvalidOperationException("任务栏恢复保护未启动");}
 void ShellShown(IntPtr hook,uint ev,IntPtr window,int obj,int child,uint thread,uint time){if(!disposed&&Hidden&&obj==0&&IsTaskbar(window)){if(!originals.ContainsKey(window))originals[window]=true;ShowWindow(window,0);}}
 IntPtr Keyboard(int code,IntPtr message,IntPtr data){if(code>=0&&Marshal.ReadInt32(data)==0x7b){int msg=message.ToInt32();bool down=msg==0x100||msg==0x104,up=msg==0x101||msg==0x105;if(down||up){bool modified=down&&new[]{0x10,0x11,0x12,0x5b,0x5c}.Any(key=>(GetAsyncKeyState(key)&0x8000)!=0);if(HandleF12(down,modified))return new IntPtr(1);}}return CallNextHookEx(keyHook,code,message,data);}
 public bool HandleF12(bool down,bool modified){if(disposed)return false;if(!down){bool consumed=keyDown;keyDown=false;return consumed;}if(modified&&!keyDown)return false;if(keyDown)return true;keyDown=true;dispatcher.BeginInvoke(new Action(()=>{if(!disposed){Toggles++;SetHidden(!Hidden);}}),DispatcherPriority.Input);return true;}
 public void SetHidden(bool hidden,bool save=true){if(disposed||(!testing&&!Ready))return;Hidden=hidden;if(!testing)SetAppbarState(hidden?originalState|1:originalState);Enforce();if(save&&!testing)try{File.WriteAllText(optionsPath,new JavaScriptSerializer().Serialize(new{hidden=Hidden}),System.Text.Encoding.UTF8);}catch(Exception ex){Error=ex.Message;}Record();}
 public void Toggle(){Toggles++;SetHidden(!Hidden);}
 public void Enforce(){if(disposed)return;foreach(var window in targets().ToArray()){if(!IsWindow(window))continue;if(!originals.ContainsKey(window))originals[window]=IsWindowVisible(window);if(Hidden){if(IsWindowVisible(window))ShowWindow(window,0);}else if(!IsWindowVisible(window))ShowWindow(window,8);}Record();}
 void Restore(){if(!testing)SetAppbarState(originalState);foreach(var pair in originals)if(IsWindow(pair.Key))ShowWindow(pair.Key,pair.Value?8:0);Hidden=false;}
 public void Record(){if(testing)return;try{DeferredDiagnostics.Write(Path.Combine(Program.S.Root,"taskbar-visibility-state.json"),new JavaScriptSerializer().Serialize(new{time=DateTimeOffset.Now.ToString("o"),Hidden,ready=Ready,Toggles,Error,originalAppbarState=originalState,currentAppbarState=ReadAppbarState(),guardRunning=guard!=null&&!guard.HasExited,windows=targets().Select(window=>new{handle=window.ToInt64(),visible=IsWindowVisible(window)}).ToArray(),scope="Only Shell_TrayWnd and Shell_SecondaryTrayWnd; F12 only, modifier combinations passed through; normal exit restores original visibility and appbar state, native helper restores taskbar if parent exits unexpectedly."}));}catch{}}
 public void Dispose(){if(disposed)return;disposed=true;repair.Stop();if(keyHook!=IntPtr.Zero)UnhookWindowsHookEx(keyHook);if(eventHook!=IntPtr.Zero)UnhookWinEvent(eventHook);keyHook=eventHook=IntPtr.Zero;Restore();if(guardStop!=null){guardStop.Set();guardStop.Dispose();guardStop=null;}if(guard!=null){guard.Dispose();guard=null;}}
}
public static class TaskbarVisibilityTests {
 public static void Run(Action<string,bool> check){var first=new Window{Title="任务栏隔离一",Width=120,Height=80,ShowInTaskbar=false};var second=new Window{Title="任务栏隔离二",Width=120,Height=80,ShowInTaskbar=false};first.Show();second.Show();var a=new WindowInteropHelper(first).Handle;var b=new WindowInteropHelper(second).Handle;var windows=new List<IntPtr>{a,b};using(var service=new TaskbarVisibility(true,()=>windows)){service.SetHidden(true);check("隐藏任务栏共享路径实际隐藏多个隔离窗口",!TaskbarVisibility.WindowShown(a)&&!TaskbarVisibility.WindowShown(b));service.SetHidden(false);check("恢复任务栏共享路径实际恢复多个隔离窗口",TaskbarVisibility.WindowShown(a)&&TaskbarVisibility.WindowShown(b));service.HandleF12(true,false);service.HandleF12(true,false);first.Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));check("F12按住仅切换一次",service.Hidden&&service.Toggles==1);service.HandleF12(false,false);service.HandleF12(true,false);first.Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));service.HandleF12(false,false);check("F12再次按下能够恢复",!service.Hidden&&TaskbarVisibility.WindowShown(a)&&service.Toggles==2);check("带修饰键的F12不接管",!service.HandleF12(true,true)&&!service.HandleF12(false,false));service.SetHidden(true);first.Show();service.Enforce();check("系统重新显示时重新隐藏的共用路径有效",!TaskbarVisibility.WindowShown(a));service.Dispose();check("退出恢复先前可见状态",TaskbarVisibility.WindowShown(a)&&TaskbarVisibility.WindowShown(b));}first.Close();second.Close();}
}
public static class TaskbarProbe {
 public static void Run(){var app=new Application{ShutdownMode=ShutdownMode.OnMainWindowClose};var host=new Window{Title="rushbin F12 任务栏验收",Width=460,Height=180,WindowStartupLocation=WindowStartupLocation.CenterScreen,Content=new System.Windows.Controls.TextBlock{Text="F12：显示 / 隐藏系统任务栏\n关闭此验收窗口恢复任务栏",Margin=new Thickness(25),FontSize=20,TextWrapping=TextWrapping.Wrap}};app.MainWindow=host;app.Startup+=(o,e)=>{Program.Taskbar=new TaskbarVisibility();};app.Run(host);}
}
}
